INSERT INTO faq_entries (locale, topic, question, answer_md, answer_html, position) VALUES
  ('en', 'undos', 'Is the first undo on a board really free?', 'Yes. The first undo on every board is free, never comes out of your tank and cannot run out. After that, undos come from a tank of five that refills one every twenty-five minutes, or five for 250 coins, or two for a rewarded video.', '<p>Yes. The first undo on every board is free, never comes out of your tank and cannot run out. After that, undos come from a tank of five that refills one every twenty-five minutes, or five for 250 coins, or two for a rewarded video.</p>', 0),
  ('en', 'lives', 'How many lives do I get, and when is one spent?', 'Five, or eight while you hold the Brick Pass, and one comes back every thirty minutes. A life is spent only when you run out of moves and choose Try again, or leave a board you have already made a move on.', '<p>Five, or eight while you hold the Brick Pass, and one comes back every thirty minutes. A life is spent only when you run out of moves and choose Try again, or leave a board you have already made a move on.</p>', 1),
  ('en', 'ads', 'Does OutBrick show ads?', 'Only rewarded video, and only when you press a button asking for something. There are no banners, no interstitials and no ad when the app opens. Remove Ads is a one-time $4.99 purchase.', '<p>Only rewarded video, and only when you press a button asking for something. There are no banners, no interstitials and no ad when the app opens. Remove Ads is a one-time $4.99 purchase.</p>', 2),
  ('en', 'moves', 'Is there a timer?', 'No. Every board has a move limit, shown beside your move count from the first tap, but there is no clock or countdown. Reaching the limit offers five more moves for coins or a video before anything else happens.', '<p>No. Every board has a move limit, shown beside your move count from the first tap, but there is no clock or countdown. Reaching the limit offers five more moves for coins or a video before anything else happens.</p>', 3),
  ('en', 'purchases', 'How do I restore a purchase?', 'Open Shop, then choose Restore purchases. Apple processes the transaction through your Apple ID.', '<p>Open Shop, then choose Restore purchases. Apple processes the transaction through your Apple ID.</p>', 4),
  ('en', 'stars', 'What do the three stars mean?', 'One star for clearing the board, the second for clearing it at or under the target move count, and the third for doing that without an undo. The target used to be called par; it is the same number.', '<p>One star for clearing the board, the second for clearing it at or under the target move count, and the third for doing that without an undo. The target used to be called par; it is the same number.</p>', 5),
  ('en', 'moves', 'How much do extra moves cost?', 'Five more moves cost 300 coins, then 500, then 900 within one attempt, or one rewarded video. The price goes back to 300 when you leave the board or clear it.', '<p>Five more moves cost 300 coins, then 500, then 900 within one attempt, or one rewarded video. The price goes back to 300 when you leave the board or clear it.</p>', 6),
  ('en', 'ads', 'How many rewarded videos can I watch a day?', 'Thirty-one at most across the six rewards, each capped daily. Declining never changes a reward, a board or a price.', '<p>Thirty-one at most across the six rewards, each capped daily. Declining never changes a reward, a board or a price.</p>', 7),
  ('en', 'accessibility', 'How do I turn colour-blind glyphs on or off?', 'Colour-blind mode is on by default, so every brick and gate carries a readable glyph. Switch it off, or back on, in Settings.', '<p>Colour-blind mode is on by default, so every brick and gate carries a readable glyph. Switch it off, or back on, in Settings.</p>', 8),
  ('en', 'privacy', 'How do I change my advertising choices?', 'In the EEA, the UK and Switzerland, Settings, then Advertising choices, reopens the consent form at any time. iOS tracking permission is in Settings, Privacy and Security, Tracking; saying no changes nothing about the game.', '<p>In the EEA, the UK and Switzerland, Settings, then Advertising choices, reopens the consent form at any time. iOS tracking permission is in Settings, Privacy and Security, Tracking; saying no changes nothing about the game.</p>', 9),
  ('en', 'contact', 'How do I contact OutBrick support?', 'Use the contact form, and tell us the level number, device model, iOS version and what happened. We never need your Game Center login or any payment details.', '<p>Use the contact form, and tell us the level number, device model, iOS version and what happened. We never need your Game Center login or any payment details.</p>', 10),
  ('fr', 'undos', 'La première annulation est-elle vraiment gratuite ?', 'Oui. Sur chaque plateau, la première annulation est gratuite, ne touche pas la réserve et ne s’épuise jamais. Ensuite, la réserve de cinq se recharge d’une toutes les vingt-cinq minutes, ou de cinq pour 250 pièces, ou de deux pour une vidéo récompensée.', '<p>Oui. Sur chaque plateau, la première annulation est gratuite, ne touche pas la réserve et ne s’épuise jamais. Ensuite, la réserve de cinq se recharge d’une toutes les vingt-cinq minutes, ou de cinq pour 250 pièces, ou de deux pour une vidéo récompensée.</p>', 0),
  ('fr', 'lives', 'Combien de vies ai-je, et quand en dépense-t-on une ?', 'Cinq, huit avec le Brick Pass ; une revient toutes les trente minutes. Une vie est dépensée uniquement si vous manquez de coups et choisissez Réessayer, ou quittez un plateau où vous avez déjà joué.', '<p>Cinq, huit avec le Brick Pass ; une revient toutes les trente minutes. Une vie est dépensée uniquement si vous manquez de coups et choisissez Réessayer, ou quittez un plateau où vous avez déjà joué.</p>', 1),
  ('fr', 'ads', 'OutBrick affiche-t-il des publicités ?', 'Uniquement des vidéos récompensées, après appui volontaire pour une récompense. Sans bannières, interstitiels ni publicité au lancement. Remove Ads est un achat unique de 4,99 $ US.', '<p>Uniquement des vidéos récompensées, après appui volontaire pour une récompense. Sans bannières, interstitiels ni publicité au lancement. Remove Ads est un achat unique de 4,99 $ US.</p>', 2),
  ('fr', 'moves', 'Y a-t-il un minuteur ?', 'Non. Chaque plateau affiche une limite de coups près du compteur dès le premier toucher, sans horloge ni compte à rebours. À la limite, cinq coups supplémentaires sont proposés contre pièces ou vidéo avant toute autre action.', '<p>Non. Chaque plateau affiche une limite de coups près du compteur dès le premier toucher, sans horloge ni compte à rebours. À la limite, cinq coups supplémentaires sont proposés contre pièces ou vidéo avant toute autre action.</p>', 3),
  ('fr', 'purchases', 'Comment restaurer un achat ?', 'Ouvrez la boutique, puis Restaurer les achats. Apple traite la transaction via votre identifiant Apple.', '<p>Ouvrez la boutique, puis Restaurer les achats. Apple traite la transaction via votre identifiant Apple.</p>', 4),
  ('fr', 'stars', 'Que signifient les trois étoiles ?', 'Une pour terminer, la deuxième à l’objectif ou en dessous, la troisième pour le faire sans annulation. L’objectif s’appelait auparavant par : c’est le même nombre.', '<p>Une pour terminer, la deuxième à l’objectif ou en dessous, la troisième pour le faire sans annulation. L’objectif s’appelait auparavant par : c’est le même nombre.</p>', 5),
  ('fr', 'moves', 'Combien coûtent les coups supplémentaires ?', 'Cinq coups coûtent 300 pièces, puis 500, puis 900 dans un même essai, ou une vidéo récompensée. Le prix revient à 300 en quittant ou terminant le plateau.', '<p>Cinq coups coûtent 300 pièces, puis 500, puis 900 dans un même essai, ou une vidéo récompensée. Le prix revient à 300 en quittant ou terminant le plateau.</p>', 6),
  ('fr', 'ads', 'Combien de vidéos récompensées par jour ?', 'Au plus trente et une, réparties sur six récompenses plafonnées chaque jour. Refuser ne change jamais récompense, plateau ou prix.', '<p>Au plus trente et une, réparties sur six récompenses plafonnées chaque jour. Refuser ne change jamais récompense, plateau ou prix.</p>', 7),
  ('fr', 'accessibility', 'Comment activer ou désactiver les glyphes daltonisme ?', 'Le mode est actif par défaut : chaque brique et porte porte un glyphe lisible. Désactivez-le ou réactivez-le dans les réglages.', '<p>Le mode est actif par défaut : chaque brique et porte porte un glyphe lisible. Désactivez-le ou réactivez-le dans les réglages.</p>', 8),
  ('fr', 'privacy', 'Comment modifier mes choix publicitaires ?', 'Dans l’EEE, au Royaume-Uni et en Suisse, Réglages puis Choix publicitaires rouvre le consentement à tout moment. L’autorisation de suivi iOS est dans Réglages, Confidentialité et sécurité, Suivi ; refuser ne change pas le jeu.', '<p>Dans l’EEE, au Royaume-Uni et en Suisse, Réglages puis Choix publicitaires rouvre le consentement à tout moment. L’autorisation de suivi iOS est dans Réglages, Confidentialité et sécurité, Suivi ; refuser ne change pas le jeu.</p>', 9),
  ('fr', 'contact', 'Comment contacter l’assistance OutBrick ?', 'Utilisez le formulaire avec numéro de niveau, modèle d’appareil, version iOS et faits. Nous ne demandons jamais identifiants Game Center ni détails de paiement.', '<p>Utilisez le formulaire avec numéro de niveau, modèle d’appareil, version iOS et faits. Nous ne demandons jamais identifiants Game Center ni détails de paiement.</p>', 10),
  ('de', 'undos', 'Ist die erste Zugrücknahme eines Feldes wirklich gratis?', 'Ja. Die erste Zugrücknahme jedes Feldes ist gratis, wird nie vom Vorrat abgezogen und kann nicht ausgehen. Danach kommen Zugrücknahmen aus einem Vorrat von fünf, der alle fünfundzwanzig Minuten eine ergänzt, oder fünf für 250 Münzen oder zwei für ein Belohnungsvideo.', '<p>Ja. Die erste Zugrücknahme jedes Feldes ist gratis, wird nie vom Vorrat abgezogen und kann nicht ausgehen. Danach kommen Zugrücknahmen aus einem Vorrat von fünf, der alle fünfundzwanzig Minuten eine ergänzt, oder fünf für 250 Münzen oder zwei für ein Belohnungsvideo.</p>', 0),
  ('de', 'lives', 'Wie viele Leben bekomme ich, und wann wird eines verbraucht?', 'Fünf oder acht mit Brick Pass; alle dreißig Minuten kommt eines zurück. Ein Leben wird nur verbraucht, wenn du keine Züge mehr hast und ‚Erneut versuchen‘ wählst oder ein Feld verlässt, auf dem du bereits gezogen hast.', '<p>Fünf oder acht mit Brick Pass; alle dreißig Minuten kommt eines zurück. Ein Leben wird nur verbraucht, wenn du keine Züge mehr hast und ‚Erneut versuchen‘ wählst oder ein Feld verlässt, auf dem du bereits gezogen hast.</p>', 1),
  ('de', 'ads', 'Zeigt OutBrick Werbung?', 'Nur Belohnungsvideos und nur, wenn du etwas per Knopfdruck anforderst. Keine Banner, keine Unterbrechungswerbung, keine Werbung beim App-Start. Werbung entfernen ist ein einmaliger Kauf für $4.99.', '<p>Nur Belohnungsvideos und nur, wenn du etwas per Knopfdruck anforderst. Keine Banner, keine Unterbrechungswerbung, keine Werbung beim App-Start. Werbung entfernen ist ein einmaliger Kauf für $4.99.</p>', 2),
  ('de', 'moves', 'Gibt es einen Timer?', 'Nein. Jedes Feld zeigt ab dem ersten Tippen ein Zuglimit neben dem Zugzähler, aber keine Uhr oder keinen Countdown. Beim Erreichen werden zuerst fünf weitere Züge für Münzen oder ein Video angeboten.', '<p>Nein. Jedes Feld zeigt ab dem ersten Tippen ein Zuglimit neben dem Zugzähler, aber keine Uhr oder keinen Countdown. Beim Erreichen werden zuerst fünf weitere Züge für Münzen oder ein Video angeboten.</p>', 3),
  ('de', 'purchases', 'Wie stelle ich einen Kauf wieder her?', 'Öffne den Shop und wähle Käufe wiederherstellen. Apple bearbeitet die Transaktion über deine Apple-ID.', '<p>Öffne den Shop und wähle Käufe wiederherstellen. Apple bearbeitet die Transaktion über deine Apple-ID.</p>', 4),
  ('de', 'stars', 'Was bedeuten die drei Sterne?', 'Ein Stern fürs Lösen, der zweite fürs Lösen innerhalb oder unterhalb der Zugvorgabe und der dritte dafür ohne Zugrücknahme. Die Vorgabe hieß früher Par; es ist dieselbe Zahl.', '<p>Ein Stern fürs Lösen, der zweite fürs Lösen innerhalb oder unterhalb der Zugvorgabe und der dritte dafür ohne Zugrücknahme. Die Vorgabe hieß früher Par; es ist dieselbe Zahl.</p>', 5),
  ('de', 'moves', 'Wie viel kosten zusätzliche Züge?', 'Fünf weitere Züge kosten innerhalb eines Versuchs 300, dann 500, dann 900 Münzen oder ein Belohnungsvideo. Beim Verlassen oder Lösen des Feldes kehrt der Preis zu 300 zurück.', '<p>Fünf weitere Züge kosten innerhalb eines Versuchs 300, dann 500, dann 900 Münzen oder ein Belohnungsvideo. Beim Verlassen oder Lösen des Feldes kehrt der Preis zu 300 zurück.</p>', 6),
  ('de', 'ads', 'Wie viele Belohnungsvideos darf ich täglich ansehen?', 'Höchstens einunddreißig über sechs Belohnungen, jede täglich begrenzt. Ablehnen verändert weder Belohnung noch Feld oder Preis.', '<p>Höchstens einunddreißig über sechs Belohnungen, jede täglich begrenzt. Ablehnen verändert weder Belohnung noch Feld oder Preis.</p>', 7),
  ('de', 'accessibility', 'Wie schalte ich Farbenblind-Symbole ein oder aus?', 'Der Farbenblind-Modus ist standardmäßig aktiv, daher trägt jeder Stein und jedes Tor ein lesbares Symbol. In Einstellungen kannst du ihn aus- oder wieder einschalten.', '<p>Der Farbenblind-Modus ist standardmäßig aktiv, daher trägt jeder Stein und jedes Tor ein lesbares Symbol. In Einstellungen kannst du ihn aus- oder wieder einschalten.</p>', 8),
  ('de', 'privacy', 'Wie ändere ich meine Werbeentscheidungen?', 'Im EWR, Großbritannien und der Schweiz öffnet Einstellungen, Werbeentscheidungen das Einwilligungsformular jederzeit wieder. Die iOS-Tracking-Erlaubnis liegt unter Einstellungen, Datenschutz & Sicherheit, Tracking; Ablehnen ändert am Spiel nichts.', '<p>Im EWR, Großbritannien und der Schweiz öffnet Einstellungen, Werbeentscheidungen das Einwilligungsformular jederzeit wieder. Die iOS-Tracking-Erlaubnis liegt unter Einstellungen, Datenschutz &amp; Sicherheit, Tracking; Ablehnen ändert am Spiel nichts.</p>', 9),
  ('de', 'contact', 'Wie kontaktiere ich die OutBrick-Hilfe?', 'Nutze das Kontaktformular und nenne Levelnummer, Gerätemodell, iOS-Version und was passiert ist. Wir brauchen nie deinen Game-Center-Zugang oder Zahlungsdaten.', '<p>Nutze das Kontaktformular und nenne Levelnummer, Gerätemodell, iOS-Version und was passiert ist. Wir brauchen nie deinen Game-Center-Zugang oder Zahlungsdaten.</p>', 10),
  ('es', 'undos', '¿De verdad es gratis el primer deshacer de un tablero?', 'Sí. El primero de cada tablero es gratis, no sale de tu reserva y no se agota. Después salen de una reserva de cinco que recupera uno cada veinticinco minutos, o cinco por 250 monedas, o dos por un vídeo con recompensa.', '<p>Sí. El primero de cada tablero es gratis, no sale de tu reserva y no se agota. Después salen de una reserva de cinco que recupera uno cada veinticinco minutos, o cinco por 250 monedas, o dos por un vídeo con recompensa.</p>', 0),
  ('es', 'lives', '¿Cuántas vidas tengo y cuándo se consume una?', 'Cinco, u ocho mientras tengas Brick Pass, y recuperas una cada treinta minutos. Solo consumes una al quedarte sin movimientos y elegir Reintentar, o al dejar un tablero donde ya has movido.', '<p>Cinco, u ocho mientras tengas Brick Pass, y recuperas una cada treinta minutos. Solo consumes una al quedarte sin movimientos y elegir Reintentar, o al dejar un tablero donde ya has movido.</p>', 1),
  ('es', 'ads', '¿OutBrick muestra anuncios?', 'Solo vídeos con recompensa cuando pulsas un botón para pedir algo. Sin banners, intersticiales ni anuncio al abrir. Remove Ads es una compra única de $4.99.', '<p>Solo vídeos con recompensa cuando pulsas un botón para pedir algo. Sin banners, intersticiales ni anuncio al abrir. Remove Ads es una compra única de $4.99.</p>', 2),
  ('es', 'moves', '¿Hay temporizador?', 'No. Cada tablero tiene un límite de movimientos junto al contador desde el primer toque, pero ningún reloj ni cuenta atrás. Al alcanzarlo se ofrecen cinco movimientos más por monedas o un vídeo antes de que ocurra nada más.', '<p>No. Cada tablero tiene un límite de movimientos junto al contador desde el primer toque, pero ningún reloj ni cuenta atrás. Al alcanzarlo se ofrecen cinco movimientos más por monedas o un vídeo antes de que ocurra nada más.</p>', 3),
  ('es', 'purchases', '¿Cómo restauro una compra?', 'Abre Tienda y elige Restaurar compras. Apple procesa la transacción mediante tu Apple ID.', '<p>Abre Tienda y elige Restaurar compras. Apple procesa la transacción mediante tu Apple ID.</p>', 4),
  ('es', 'stars', '¿Qué significan las tres estrellas?', 'Una por despejar, la segunda por hacerlo en el objetivo o menos movimientos y la tercera por hacerlo sin deshacer. El objetivo antes se llamaba par; es el mismo número.', '<p>Una por despejar, la segunda por hacerlo en el objetivo o menos movimientos y la tercera por hacerlo sin deshacer. El objetivo antes se llamaba par; es el mismo número.</p>', 5),
  ('es', 'moves', '¿Cuánto cuestan los movimientos extra?', 'Cinco movimientos más cuestan 300 monedas, después 500 y después 900 en un intento, o un vídeo con recompensa. El precio vuelve a 300 cuando sales o despejas.', '<p>Cinco movimientos más cuestan 300 monedas, después 500 y después 900 en un intento, o un vídeo con recompensa. El precio vuelve a 300 cuando sales o despejas.</p>', 6),
  ('es', 'ads', '¿Cuántos vídeos con recompensa puedo ver al día?', 'Como máximo treinta y uno entre las seis recompensas, cada una con tope diario. Rechazarlos nunca cambia una recompensa, tablero ni precio.', '<p>Como máximo treinta y uno entre las seis recompensas, cada una con tope diario. Rechazarlos nunca cambia una recompensa, tablero ni precio.</p>', 7),
  ('es', 'accessibility', '¿Cómo activo o desactivo los símbolos para daltonismo?', 'El modo está activo por defecto y cada ladrillo y puerta lleva un símbolo legible. Desactívalo o vuelve a activarlo en Ajustes.', '<p>El modo está activo por defecto y cada ladrillo y puerta lleva un símbolo legible. Desactívalo o vuelve a activarlo en Ajustes.</p>', 8),
  ('es', 'privacy', '¿Cómo cambio mis preferencias publicitarias?', 'En el EEE, Reino Unido y Suiza, Ajustes y después Opciones de publicidad abre el consentimiento cuando quieras. El permiso de seguimiento de iOS está en Ajustes, Privacidad y seguridad, Seguimiento; rechazarlo no cambia el juego.', '<p>En el EEE, Reino Unido y Suiza, Ajustes y después Opciones de publicidad abre el consentimiento cuando quieras. El permiso de seguimiento de iOS está en Ajustes, Privacidad y seguridad, Seguimiento; rechazarlo no cambia el juego.</p>', 9),
  ('es', 'contact', '¿Cómo contacto con la ayuda de OutBrick?', 'Usa el formulario e indica nivel, modelo del dispositivo, versión de iOS y qué ocurrió. Nunca necesitamos tu acceso a Game Center ni datos de pago.', '<p>Usa el formulario e indica nivel, modelo del dispositivo, versión de iOS y qué ocurrió. Nunca necesitamos tu acceso a Game Center ni datos de pago.</p>', 10),
  ('ja', 'undos', '最初のアンドゥは本当に無料？', 'はい。各ステージ最初は無料で、タンクから減らず、なくなりません。その後は5回分のタンクが25分ごとに1回回復、250コインで5回、リワード動画で2回です。', '<p>はい。各ステージ最初は無料で、タンクから減らず、なくなりません。その後は5回分のタンクが25分ごとに1回回復、250コインで5回、リワード動画で2回です。</p>', 0),
  ('ja', 'lives', 'ライフは何個、いつ使いますか？', '5つ、Brick Pass保有中は8つで、30分ごとに1つ回復。手数切れで再挑戦を選ぶか、すでに動かした盤面を離れる場合だけ使います。', '<p>5つ、Brick Pass保有中は8つで、30分ごとに1つ回復。手数切れで再挑戦を選ぶか、すでに動かした盤面を離れる場合だけ使います。</p>', 1),
  ('ja', 'ads', '広告はありますか？', '何かを求めるボタンを押したときのリワード動画だけです。バナー、割り込み、起動広告はありません。広告削除は一度の$4.99購入です。', '<p>何かを求めるボタンを押したときのリワード動画だけです。バナー、割り込み、起動広告はありません。広告削除は一度の$4.99購入です。</p>', 2),
  ('ja', 'moves', 'タイマーはありますか？', 'いいえ。最初のタップから手数上限はありますが、時計やカウントダウンはありません。上限では、先にコインか動画で5手追加を提案します。', '<p>いいえ。最初のタップから手数上限はありますが、時計やカウントダウンはありません。上限では、先にコインか動画で5手追加を提案します。</p>', 3),
  ('ja', 'purchases', '購入を復元するには？', 'ショップを開き「購入を復元」を選びます。Apple IDを通じAppleが処理します。', '<p>ショップを開き「購入を復元」を選びます。Apple IDを通じAppleが処理します。</p>', 4),
  ('ja', 'stars', '3スターの意味は？', 'クリアで1、目標手数以下で2、さらにアンドゥなしで3です。目標は以前パーと呼んでいましたが同じ数字です。', '<p>クリアで1、目標手数以下で2、さらにアンドゥなしで3です。目標は以前パーと呼んでいましたが同じ数字です。</p>', 5),
  ('ja', 'moves', '追加手数の費用は？', '一回の挑戦内で5手が300、次に500、次に900コイン、またはリワード動画1本です。離れるかクリアで300へ戻ります。', '<p>一回の挑戦内で5手が300、次に500、次に900コイン、またはリワード動画1本です。離れるかクリアで300へ戻ります。</p>', 6),
  ('ja', 'ads', '一日何本動画を見られますか？', '六つの報酬全体で最大31本、各々1日上限があります。断っても報酬、盤面、価格は変わりません。', '<p>六つの報酬全体で最大31本、各々1日上限があります。断っても報酬、盤面、価格は変わりません。</p>', 7),
  ('ja', 'accessibility', '色覚サポート記号を切り替えるには？', '初期設定で有効なので、すべてのブロックとゲートに記号があります。設定で無効・再有効にできます。', '<p>初期設定で有効なので、すべてのブロックとゲートに記号があります。設定で無効・再有効にできます。</p>', 8),
  ('ja', 'privacy', '広告の選択を変えるには？', 'EEA、英国、スイスでは「設定」「広告の選択」でいつでも同意フォームを開けます。iOSの追跡許可は「設定」「プライバシーとセキュリティ」「トラッキング」。拒否しても遊びは変わりません。', '<p>EEA、英国、スイスでは「設定」「広告の選択」でいつでも同意フォームを開けます。iOSの追跡許可は「設定」「プライバシーとセキュリティ」「トラッキング」。拒否しても遊びは変わりません。</p>', 9),
  ('ja', 'contact', 'サポートへ連絡するには？', 'フォームでステージ番号、機器、iOS版、起きたことを教えてください。Game Centerログインや支払情報は要りません。', '<p>フォームでステージ番号、機器、iOS版、起きたことを教えてください。Game Centerログインや支払情報は要りません。</p>', 10);
